def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Remove build metadata (+ and everything after)
        v = v.split('+')[0]

        # Split into core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v
            prerelease_parts = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre_a, pre_b):
        # If neither has prerelease, they're equal
        if pre_a is None and pre_b is None:
            return 0
        # If only one has prerelease, the one without is higher
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare prerelease identifiers
        for i in range(max(len(pre_a), len(pre_b))):
            # More identifiers is higher precedence
            if i >= len(pre_a):
                return -1
            if i >= len(pre_b):
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if identifiers are numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            if is_num_a and is_num_b:
                # Both numeric: compare numerically
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            elif is_num_a:
                # Only a is numeric: numeric has lower precedence
                return -1
            elif is_num_b:
                # Only b is numeric: numeric has lower precedence
                return 1
            else:
                # Both non-numeric: compare ASCII order
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare core version
    if major_a < major_b:
        return -1
    elif major_a > major_b:
        return 1

    if minor_a < minor_b:
        return -1
    elif minor_a > minor_b:
        return 1

    if patch_a < patch_b:
        return -1
    elif patch_a > patch_b:
        return 1

    # Core versions are equal, compare prerelease
    return compare_prerelease(pre_a, pre_b)

